import{_ as B,H as e,f as A,i as t}from"./chunks/framework.BH2BK_3i.js";const r=JSON.parse('{"title":"第二十九封信-什么相机是最好的相机？（成像质量）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第二十九封信-什么相机是最好的相机？（成像质量）.md","filePath":"去无方向的信/第二十九封信-什么相机是最好的相机？（成像质量）.md","lastUpdated":1795542896000}'),i={name:"去无方向的信/第二十九封信-什么相机是最好的相机？（成像质量）.md"};function s(C,E,n,F,a,p){return e(),A("div",null,[...E[0]||(E[0]=[t('<h1 id="第二十九封信-什么相机是最好的相机-成像质量" tabindex="-1">第二十九封信-什么相机是最好的相机？（成像质量） <a class="header-anchor" href="#第二十九封信-什么相机是最好的相机-成像质量" aria-label="Permalink to &quot;第二十九封信-什么相机是最好的相机？（成像质量）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/3.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>上次聊了什么叫“画幅越大，拍到的画面就越广”，这次我们来聊聊成像质量。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/4.png" alt=""></a></p><ul><li>135 / 6x7 中画幅 / 4x5 大画幅</li></ul><p>左边这张小的是 35mm 胶片（135 胶片）的大小，中间这张是 6x7 中画幅胶片的大小，最后这张大的，是 4x5 大画幅胶片的大小。</p><p>我们知道，以前玛格南的那帮老派纪实摄影师用的都是 35mm 胶片，但他们的作品冲印成家里常挂的那种装饰画大小的成品的时候，比如他们办展览，幅面都还可以，而且画质依然非常精细……问题是，35mm 胶片的面积这么小，为什么冲印成较大幅面的成品的时候，没有画质损失？</p><p>其实是有的，只是在输出面积还不够大的时候，你看不出来。</p><p>顺着这个逻辑看中间那张 6x7 中画幅胶片，如果说 35mm 胶片可以冲印成装饰画大小的成品，那么你想想，中画幅胶片的底片比 35mm 胶片的底片大了那么多，一张 6x7 中画幅胶片的面积大约是四张 35mm 胶片的大小，所以很自然的，中画幅可以输出更大幅面的成品。</p><p>顺着这个逻辑看右边那张 4x5 大画幅胶片，他基本上是四张 6x7 中画幅底片的大小，可想而知他能输出出来多大幅面的成品。当然，现在我们讨论的还是在没有可见画质损失的前提下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/5.png" alt=""></a></p><ul><li>石内都（135）</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/6.jpeg" alt=""></a></p><ul><li>Bernard Faucon（中画幅）</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/7.png" alt=""></a></p><ul><li>Andreas Gursky（大画幅）</li></ul><p>Andreas Gursky 最大的作品可以占满一整面墙，站在那样的照片儿前面，看不到照片框，像IMAX 一样，仿佛置身其中，仿佛我就在拍摄现场。世界上目前最贵的照片儿就是这个人拍的，叫 Rhein II（莱茵河 2 号），430 万美元。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/8.png" alt=""></a></p><ul><li>Rhein IIAndreas Gursky</li></ul><p>就这？！哈哈哈，咱们以后会讲到，为什么这样一张无聊的东西能卖到 430 万美元。</p><p>说回到我们的正题上，现在有个问题，我们已经不怎么用胶片拍照片儿了，全是数码，所以比较这么多胶片的大小干嘛？</p><p>别急，你得先对这些画幅的大小关系有一个直观的印象，然后跟数码有关的内容这就来了。</p><p>我们可以把一张 35mm 胶片印成 6 吋的照片儿，放在自家的影集里，供多年后回忆青春；我们也可以把一张 35mm 胶片印成大海报，挂在家里的墙上；我们还可以把一张 35mm 胶片冲印成巨大的，巨巨巨大的，像糖纸包糖豆一样把地球包上……问题是，如果一张 35mm 胶片被冲印到那么大，我们脚下的画面会不会都是像素格？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/9.png" alt=""></a></p><p>不会，因为胶片是实实在在的物质，如果冲印到那么大，画面上的颗粒感会非常重，我们脚下的画面有可能会是巨大的颗粒，但不会有“像素格”这个东西，因为像素这个概念是专属于数码的。</p><p>像素就是一个一个的小格子，他是数码影像最小的单位，所以一个格子只能有一个颜色，拼起来，变成了一张图。比如上面这张例图，只有 15000 个像素，15000 个像素显然承载不了那么多画面信息，所以根本没有细节可言。</p><p>但如果同样一张照片，有 4000 万像素，情况就完全不同了。4000 万像素的意思，就是把一个画面分成 4000 万份，这 4000 万个小格子拼成了一张图，每一个小格子都会小到你肉眼无法分辨，这样一来，画质自然就比只分成 15000 份要细腻。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/10.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E4%25B9%259D%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E6%2588%2590%25E5%2583%258F%25E8%25B4%25A8%25E9%2587%258F%25EF%25BC%2589/10.jpeg" alt=""></a></p><p>顺着这个逻辑咱们继续。</p><p>首先说一下，数码相机的大家庭里也有中画幅和大画幅，所以不要以为只有胶片才有这种大尺寸画幅。</p><p>那么，如果同样都是 4000 万像素，一台相机是 APS-C 画幅，一台相机是全画幅，一台相机是中画幅，一台相机是大画幅……会是个什么情况？</p><p>同样都是分成 4000 万份，但因为总面积不一样，所以每一小份的面积也不一样。科学原理就不讲了，简单来说，面积大，处理光的能力就强，面积小，处理光的能力就弱。所以，即便是同样的像素数，在同样的条件下，比如说光线、参数和画面内容什么的，画幅的大小决定着画面的质量，画幅越大，画面就越细腻，画幅越小，画面就越粗糙。</p><p>甚至，如果极端一点，让一台卡片机和一台大画幅相机比，即便使用卡片机的拍摄环境非常理想，使用大画幅相机的拍摄环境非常不理想，大概率，也还是大画幅相机的画质会更细腻。</p><p>这就叫“底大一级压死人”，就更不要说卡片机和大画幅这种差着好几级的了。</p><p>所以，当我们看到某手机公司宣传自家手机相机 1 亿像素的时候，我们需要知道手机相机的传感器（画幅）有多小，那么小的画幅，分成 1 亿个小格子，每一个小格子那么小那么小，处理光的能力一定弱爆了，结果可想而知……总之，就是不要掉进像素的陷阱，画幅决定着画质，在画幅有碾压性优势的时候，像素高低没那么重要。</p><p>（防杠注：宣传自家手机相机 1 亿像素的厂商，他们有解释过，其实那不是真正的 1 亿像素，是靠算法合成……哎呀，解释起来好麻烦，总之就是，不冤枉他们，他们解释过，那不是真正的 1 亿像素。）</p><p>但是，我必须得说，现在的手机其实也还挺厉害的，虽然手机相机画幅小，但是处理器牛啊，有很多很多的算法，可以弥补光学上和电子上的不足。但如果有一天，专业相机也用上了那么高级的传感器，用上了那么高级的算法，手机自然就还是没戏。</p><p>没有贬损手机的意思，纯粹只是陈述客观事实。</p><p>另外还得补充一句，我认为，相机，尤其是专业相机，不会用手机上的那种算法，因为专业相机和手机相机是两种完全不同的东西，咱们之后会说到。</p><p>无论如何，说了半天，反正画幅大就是好啊，所以，问题来了，如果画幅越大越好，我们为什么不都用大画幅相机拍照片儿呢？咱们有时间再继续聊。</p>',44)])])}const g=B(i,[["render",s]]);export{r as __pageData,g as default};
